/* Compteurs indépendants des montants de congés et des versements CIBTP. */
const leaveFields=['leaveN1','leaveN','leaveTakenN1','leaveTakenN','leaveAcquiredMonth','leaveCycle','leaveAsOf'];
function leaveInputs(v,profile=false){return section('Compteurs de congés · N−1 et N',field('leaveCycle','Période / cycle de congés (ex. 2025–2026)',v.leaveCycle||'')+field('leaveAsOf',profile?'Situation des compteurs au':'Situation de départ au',v.leaveAsOf||'','date')+(profile?selectField('leaveUnit','Unité des compteurs',v.leaveUnit||'Ouvrables',['Ouvrables','Ouvrés']):'')+field('leaveN1','Congés acquis N−1 (jours)',v.leaveN1??'','number','min="0" step=".000001"')+field('leaveN','Congés acquis N (jours), avant acquisition du mois',v.leaveN??'','number','min="0" step=".000001"')+num('leaveTakenN1','Congés N−1 déjà pris avant ce mois',v.leaveTakenN1||0)+num('leaveTakenN','Congés N déjà pris avant ce mois',v.leaveTakenN||0)+(profile?'':num('leaveAcquiredMonth','Congés acquis pendant ce mois — à confirmer',v.leaveAcquiredMonth||0))+`<div class="wide notice" id="${profile?'profileLeaveLive':'balanceLive'}" aria-live="polite">Compteurs à renseigner.</div><p class="wide muted">Solde = acquis N−1 + acquis N + acquisition saisie du mois − congés déjà pris − congés pris ce mois. Les jours du mois sont ceux du champ « Congés pris ». Imputation N−1 puis N, à vérifier selon les droits reportés. L’acquisition et le report sont paramétrables dans la section « Congés N ». Les droits supplémentaires et reports particuliers restent à vérifier. Utilisez une même unité pour tous les jours. Les compteurs restent distincts des calculs d’indemnité et du paiement CIBTP.</p>`);}
function leaveTable(v){let b;try{b=LeaveBalances.calculate(v)}catch(e){return `<p class="error">${esc(e.message)}</p>`}if(!b)return `<div class="leave-block"><h3>Congés payés · ${esc(v.cpUnit||v.leaveUnit||'Unité à renseigner')}</h3><table class="leave-table"><thead><tr><th>Droits</th><th>Acquis</th><th>Pris cumulés</th><th>Solde</th></tr></thead><tbody><tr><td>N−1</td><td>À renseigner</td><td>${esc(v.leaveTakenN1??'À renseigner')}</td><td>À calculer</td></tr><tr><td>N</td><td>À renseigner</td><td>${esc(v.leaveTakenN??'À renseigner')}</td><td>À calculer</td></tr></tbody></table><p class="muted"><strong>Congés acquis ce mois : ${v.leaveAcquiredMonth!==undefined&&v.leaveAcquiredMonth!==''?Number(v.leaveAcquiredMonth).toFixed(2)+' jours':'À renseigner'}.</strong><br>Pris ce mois : ${esc(v.cpDays??'À renseigner')} jours. Soldes de départ à initialiser.</p></div>`;return `<div class="leave-block"><h3>Congés payés · ${esc(v.cpUnit||v.leaveUnit||'Ouvrables')}${v.leaveCycle?' · '+esc(v.leaveCycle):''}</h3><div class="scroll"><table class="leave-table"><thead><tr><th>Droits</th><th>Acquis</th><th>Pris cumulés</th><th>Solde</th></tr></thead><tbody><tr><td>N−1</td><td>${b.n1.toFixed(2)}</td><td>${b.takenN1.toFixed(2)}</td><td>${b.balanceN1.toFixed(2)}</td></tr><tr><td>N</td><td>${b.n.toFixed(2)}</td><td>${b.takenN.toFixed(2)}</td><td>${b.balanceN.toFixed(2)}</td></tr><tr class="leave-total"><td>Total</td><td>${(b.n1+b.n).toFixed(2)}</td><td>${b.taken.toFixed(2)}</td><td>${b.balance.toFixed(2)}</td></tr></tbody></table></div><p class="muted"><strong>Congés acquis ce mois : ${Number(v.leaveAcquiredMonth||0).toFixed(2)} jours.</strong><br>Pris ce mois : ${b.monthTaken.toFixed(2)} jours.${v.cpLeaveHours!==undefined&&v.cpLeaveHours!==''?' Heures de congés : '+esc(v.cpLeaveHours)+' h.':''}${b.excess?' Dépassement de droits : '+b.excess.toFixed(2)+' jours, congés anticipés / correction à vérifier.':''}</p></div>`;}
const beforeLeaveRichVar=richVar;
richVar=function(p){const v=beforeLeaveRichVar(p),saved=db.vars[vkey(p)]||{};for(const name of leaveFields)if(saved[name]===undefined)v[name]=p[name]??(name==='leaveAcquiredMonth'?'0':'');if(saved.cpUnit===undefined&&p.leaveUnit)v.cpUnit=p.leaveUnit;return v;};
const beforeLeaveMarkup=variableMarkup;
variableMarkup=function(p){return beforeLeaveMarkup(p)+leaveInputs(richVar(p))+`<button type="button" class="btn secondary" onclick="copyPreviousLeave('${p.id}')">Reprendre les compteurs du mois précédent — report / cycle</button>`;};
const beforeLeaveRefresh=refreshCalculations;
refreshCalculations=function(){beforeLeaveRefresh();const form=$('#form'),out=$('#balanceLive');if(!out)return;const v=Object.fromEntries(new FormData(form));out.innerHTML=leaveTable(v);};
const beforeLeaveRead=readVariableForm;
readVariableForm=function(f){const v=beforeLeaveRead(f);if((v.leaveN1===''&&v.leaveN!=='')||(v.leaveN===''&&v.leaveN1!==''))throw Error('Renseignez les droits N−1 et N, y compris zéro confirmé.');LeaveBalances.calculate(v);return v;};
const beforeLeaveEmployee=employee;
employee=function(id){beforeLeaveEmployee(id);const p=db.people.find(p=>p.id===id)||{};$('#formError').insertAdjacentHTML('beforebegin',leaveInputs(p,true));const update=()=>{const v=Object.fromEntries(new FormData($('#form')));v.cpDays=0;$('#profileLeaveLive').innerHTML=leaveTable(v);};$('#form').oninput=update;$('#form').onchange=update;update();};
const beforeLeaveValidation=EmployeeFields.validate;
EmployeeFields.validate=function(v){beforeLeaveValidation(v);if((v.leaveN1===''&&v.leaveN!=='')||(v.leaveN===''&&v.leaveN1!==''))throw Error('Renseignez les droits N−1 et N, y compris zéro confirmé.');LeaveBalances.calculate({...v,cpDays:0});};
const beforeLeaveDraft=draftMarkup;
draftMarkup=function(d){let html=beforeLeaveDraft(d);const table=leaveTable(d.variables);return html.replace('<div class="net-block">',table+'<div class="net-block">');};
const beforeLeaveCSV=csv;
csv=function(){const rows=[['Salarié','Période','Unité','Congés N−1 acquis','Congés N acquis','Pris N−1 cumulés','Pris N cumulés','Pris ce mois','Pris total','Solde N−1','Solde N','Solde total','Congés acquis ce mois','Heures de congés','Heures prévues du mois'],...people().map(p=>{const v=richVar(p);let b;try{b=LeaveBalances.calculate(v)}catch{}return[p.name,period(),v.cpUnit,...(b?[b.n1,b.n,b.takenN1,b.takenN,b.monthTaken,b.taken,b.balanceN1,b.balanceN,b.balance]:Array(9).fill('À renseigner')),v.leaveAcquiredMonth,v.cpLeaveHours,v.cpActualHours]})];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('ma-paye-conges-'+period()+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');};
const beforeLeaveRender=render;
render=function(){beforeLeaveRender();if(view==='Préparation paie'){$('#app .tools').insertAdjacentHTML('beforeend',`<button class="btn secondary" onclick="csv()">Exporter les compteurs congés</button>`);const exportVariables=$('#app .heading button');if(exportVariables)exportVariables.onclick=()=>beforeLeaveCSV();$('#app').insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:20px"><h2>Congés · N−1, N, pris et soldes</h2>${people().map(p=>`<h3>${esc(p.name)}</h3>${leaveTable(richVar(p))}`).join('')}</section>`);}};
render();

function copyPreviousLeave(id){try{const [year,month]=period().split('-').map(Number);const prev=month===1?`${year-1}-12`:`${year}-${String(month-1).padStart(2,'0')}`;const v=db.vars[company+'|'+prev+'|'+id];if(!v)throw Error('Aucun compteur enregistré pour le mois précédent.');const b=LeaveBalances.calculate(v);if(!b)throw Error('Les compteurs du mois précédent sont incomplets.');const f=$('#form');if(f.elements.leaveCycle.value&&v.leaveCycle&&f.elements.leaveCycle.value!==v.leaveCycle)throw Error('Cycles différents : faites la reprise N−1 / N manuellement.');if(f.elements.cpUnit.value!==v.cpUnit)throw Error('Unité différente : vérifiez la reprise des compteurs.');for(const [k,val]of Object.entries({leaveN1:b.n1,leaveN:b.n,leaveTakenN1:b.takenN1,leaveTakenN:b.takenN,leaveAcquiredMonth:0,leaveCycle:v.leaveCycle||'',leaveAsOf:period()+'-01'}))f.elements[k].value=val;refreshCalculations();toast('Compteurs repris, sans bascule annuelle. Vérifiez puis enregistrez.');}catch(e){toast(e.message)}}
